using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EventSetup", menuName = "Data/BattleSceneSetups/EventSetup", order = 0)]
public class EventSetup : BattleSceneSetup
{
	[Header("Prefabs")]
	[SerializeField]
	private GameObject eventsPanel;

	[SerializeField]
	private CameraReference mainCameraReference;

	[SerializeField]
	private VoidEvent OnDisableTurnCounterText;

	public override void SetupScene()
	{
		base.SetupScene();
		OnDisableTurnCounterText.Raise();
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		CustomEventSetup currentCustomEventSetup = mapHandler.CurrentCustomEventSetup;
		if (currentCustomEventSetup is AmbushCustomEventSetup || currentCustomEventSetup is RewardCustomEventSetup || currentCustomEventSetup is MeissaBattleCustomEventSetup || currentCustomEventSetup is CorruptedChestBattleCustomEventSetup)
		{
			currentCustomEventSetup.SetupScene();
		}
		else
		{
			SetupEvent(currentCustomEventSetup as ButtonCustomEventSetup);
		}
		if (!(currentCustomEventSetup is AmbushCustomEventSetup) && !(currentCustomEventSetup is MeissaBattleCustomEventSetup))
		{
			base.PlayBGM();
		}
	}

	public override void PlayBGM()
	{
	}

	public void SetupEvent(CustomEventSetup customEventSetup)
	{
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(eventsPanel.name);
		if (@object == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(eventsPanel);
			@object = ReferenceSingleton<PoolHandler>.Instance.GetObject(eventsPanel.name);
		}
		@object.GetComponent<Canvas>().worldCamera = mainCameraReference.value;
		ButtonCustomEventSetup buttonCustomEventSetup = customEventSetup as ButtonCustomEventSetup;
		@object.GetComponent<EventsPanel>().Initialize(buttonCustomEventSetup);
	}
}
